#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];
            std::size_t idx = (v >= 100.0) ? 9 : static_cast<std::size_t>(v / 10.0);
            ++local_bins[idx];
        }

        #pragma omp critical
        {
            for (std::size_t b = 0; b < 10; ++b) {
                bins[b] += local_bins[b];
            }
        }
    }
}
